    [Fact]
    public async Task PreconstructedCatalogDecksReachScoreVictoryActionLogReplaysToFinalStateHash()
    {
        var catalog = await OfficialCardCatalog.LoadDefaultAsync(CancellationToken.None);
        var preconstructedDecks = PreconstructedDeckCatalog.Build(catalog);
        var replayDecks = preconstructedDecks;
        Assert.Equal(replayDecks.Count, replayDecks.Select(deck => deck.Id).Distinct(StringComparer.Ordinal).Count());
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(LongSwordEquipmentCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(OrnnFriendlyEquipmentStaticAuraCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(CardTrickSpellCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(FlowingTimeMirrorSpellCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(ShadowCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(TeemoSelfPowerCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(GarenSameBattlefieldStaticAuraCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(DemaciaEnvoyCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.MainDeck.Contains(PakaaCubCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.Battlefields.Contains(LostLibraryBattlefieldHighCostSpellInsightCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.Battlefields.Contains(TrifarianTrainingGroundsBattlefieldAllUnitsStaticAuraCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.Battlefields.Contains(WindHillBattlefieldAllUnitsStaticKeywordCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.Battlefields.Contains(FortifiedPositionBattlefieldDefendGrantSteadfastCardNo, StringComparer.Ordinal));
        Assert.Contains(replayDecks, deck => deck.Decklist.Battlefields.Contains(BandleTreeBattlefieldCardNo, StringComparer.Ordinal));

        foreach (var p1Deck in replayDecks)
        {
            foreach (var p2Deck in replayDecks.Where(deck => !string.Equals(deck.Id, p1Deck.Id, StringComparison.Ordinal)))
            {
                await AssertFullGameScoreVictoryActionLogReplaysToFinalStateHashAsync(
                    $"b0-full-game-preconstructed-catalog-replay-room-{p1Deck.Id}-vs-{p2Deck.Id}",
                    $"b0-full-preconstructed-catalog-replay-score-{p1Deck.Id}-vs-{p2Deck.Id}",
                    p1Deck.Decklist,
                    p2Deck.Decklist);
            }
        }
    }

    [Fact]
    public async Task OfficialDeckMidgameResolvesCrimsonSignetTreantConquestRepeatAndScoreVictoryActionLogReplaysToFinalStateHash()
    {
        var catalog = await OfficialCardCatalog.LoadDefaultAsync(CancellationToken.None);
        var p1Deck = BuildCrimsonSignetTreantOfficialDeck(catalog);
        var p2Deck = BuildSlowBattlefieldLowCurveOfficialDeck(catalog, RumbleLegendCardNo, RumbleChampionCardNo);
        var openingInitialState = BuildSeatedInitialState("b0-full-game-treant-conquest-replay-room", LowCurveReplaySeed);
        var (_, openingResult) = await DriveOfficialLowCurveDecksToNoLegalBattleSkipAsync(
            openingInitialState,
            NoopMatchJournal.Instance,
            p1Deck,
            p2Deck);
        var initialState = BuildCrimsonSignetTreantMidgameInitialState(openingResult.State);
        var journal = new RecordingMatchJournal();
        var session = new MatchSession(initialState, new CoreRuleEngine(), journal);
        var current = AcceptedCurrentResult(initialState);
        current = await DriveSpecificUnitToOwnBattlefieldAsync(
            session,
            current,
            "P1",
            CrimsonSignetTreantCardNo,
            "b0-treant-stage-source");
        current = await DriveOpponentUnitToBattlefieldAsync(
            session,
            current,
            "P2",
            "P1",
            "b0-treant-stage-defender");

        var battleResult = await DriveContestedBattlefieldToCrimsonSignetTreantConquestAsync(
            session,
            current,
            "P1",
            "b0-treant-conquest");

        AssertCrimsonSignetTreantConquestRepeat(battleResult);

        var result = await DriveBattleCloseToScoreVictoryAsync(
            session,
            battleResult,
            "b0-treant-score");

        await AssertActionLogReplaysToFinalStateHashOnlyAsync(initialState, journal, result);
        Assert.Contains(journal.Entries, entry => string.Equals(entry.CommandType, CommandTypes.PlayCard, StringComparison.Ordinal));
        Assert.Contains(journal.Entries, entry => string.Equals(entry.CommandType, CommandTypes.MoveUnit, StringComparison.Ordinal));
        Assert.Contains(journal.Entries, entry => string.Equals(entry.CommandType, CommandTypes.DeclareBattle, StringComparison.Ordinal));
        Assert.Contains(journal.Entries, entry => string.Equals(entry.CommandType, CommandTypes.EndTurn, StringComparison.Ordinal));
        AssertScoreVictory(result);
    }

    [Fact]
    public async Task OfficialDeckMidgamePaysVayneConquestReturnAndScoreVictoryActionLogReplaysToFinalStateHash()
    {
        var catalog = await OfficialCardCatalog.LoadDefaultAsync(CancellationToken.None);
        var p1Deck = BuildVayneConquestPayReturnOfficialDeck(catalog);
        var p2Deck = BuildSourceLoneBattleStaticAuraDefenderOfficialDeck(catalog);
        var openingInitialState = BuildSeatedInitialState("b0-full-game-vayne-conquest-return-replay-room", LowCurveReplaySeed);
        var (_, openingResult) = await DriveOfficialLowCurveDecksToNoLegalBattleSkipAsync(
            openingInitialState,
            NoopMatchJournal.Instance,
            p1Deck,
            p2Deck);
        var initialState = BuildVayneConquestPayReturnBattleInitialState(openingResult.State);
        var journal = new RecordingMatchJournal();
        var session = new MatchSession(initialState, new CoreRuleEngine(), journal);
        var current = AcceptedCurrentResult(initialState);

        var paymentOpened = await SubmitVayneConquestReturnDeclareBattleAsync(
            session,
            current,
            "P1",
            "b0-vayne-conquest");

        AssertVayneConquestReturnPaymentOpened(paymentOpened);

        var paid = await PayVayneConquestReturnPaymentAsync(
            session,
            paymentOpened,
            "P1",
            "b0-vayne-conquest-pay");

        AssertVayneConquestReturnPaid(paymentOpened, paid);

        var result = await DriveBattleCloseToScoreVictoryAsync(
            session,
            paid,
            "b0-vayne-score");

        await AssertActionLogReplaysToFinalStateHashOnlyAsync(initialState, journal, result);
        Assert.Contains(journal.Entries, entry => string.Equals(entry.CommandType, CommandTypes.DeclareBattle, StringComparison.Ordinal));
        Assert.Contains(journal.Entries, entry => string.Equals(entry.CommandType, CommandTypes.PayCost, StringComparison.Ordinal));
        Assert.Contains(journal.Entries, entry => string.Equals(entry.CommandType, CommandTypes.EndTurn, StringComparison.Ordinal));
        AssertScoreVictory(result);
    }

    [Fact]
