                && string.Equals(gameEvent.Payload["trigger"] as string, TriggerKinds.BattlefieldConquerDrawForOtherBattlefields, StringComparison.Ordinal));
        Assert.True(triggerIndex > conqueredIndex, $"Expected Seat of Power trigger after conquest: {JsonSerializer.Serialize(result.Events)}");

        var triggerEvent = events[triggerIndex];
        Assert.Equal("P1", triggerEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(SeatOfPowerBattlefieldConquerDrawForOtherBattlefieldsCardNo, triggerEvent.Payload["battlefieldCardNo"]);
        Assert.Equal(attackerObjectId, triggerEvent.Payload["sourceObjectId"]);
        Assert.Equal(expectedOtherBattlefieldObjectIds.Length, triggerEvent.Payload["drawCount"]);
        Assert.Equal(
            expectedOtherBattlefieldObjectIds,
            Assert.IsAssignableFrom<IReadOnlyList<string>>(triggerEvent.Payload["otherBattlefieldObjectIds"]));

        var drawEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "CARD_DRAWN", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["playerId"] as string, "P1", StringComparison.Ordinal));
        Assert.Equal(expectedDrawnObjectIds.Length, drawEvent.Payload["count"]);
        if (drawEvent.Payload.TryGetValue("cardIds", out var drawnCardIds))
        {
            Assert.Equal(expectedDrawnObjectIds, Assert.IsType<string[]>(drawnCardIds));
        }

        foreach (var drawnObjectId in expectedDrawnObjectIds)
        {
            Assert.Contains(drawnObjectId, result.State.PlayerZones["P1"].Hand);
            Assert.DoesNotContain(drawnObjectId, result.State.PlayerZones["P1"].MainDeck);
        }

        Assert.Equal(
            beforeBattle.State.PlayerZones["P1"].MainDeck.Skip(expectedDrawnObjectIds.Length).ToArray(),
            result.State.PlayerZones["P1"].MainDeck);
        Assert.DoesNotContain(defenderObjectId, result.State.PlayerZones["P2"].Battlefields);
        AssertNoHiddenZoneLeak(result);
    }

    private static void AssertBattlefieldConquerReadyEquipmentResolved(
        ResolutionResult beforeBattle,
