        var equipmentObjectId = beforeBattle.State.PlayerZones["P1"].Base
            .Single(objectId => beforeBattle.State.CardObjects.TryGetValue(objectId, out var cardObject)
                && string.Equals(cardObject.CardNo, LongSwordEquipmentCardNo, StringComparison.Ordinal));
        Assert.True(beforeBattle.State.CardObjects[equipmentObjectId].IsExhausted);
        Assert.Equal(attackerObjectId, beforeBattle.State.CardObjects[equipmentObjectId].AttachedToObjectId);
        Assert.Null(result.State.PendingPayment);

        var events = result.Events.ToArray();
        var conqueredIndex = Array.FindIndex(
            events,
            gameEvent => string.Equals(gameEvent.Kind, "BATTLEFIELD_CONQUERED", StringComparison.Ordinal)
                && string.Equals(gameEvent.Payload["battlefieldId"] as string, battlefieldObjectId, StringComparison.Ordinal));
        Assert.True(conqueredIndex >= 0, $"Expected battlefield conquered before Moonveil Altar trigger: {JsonSerializer.Serialize(result.Events)}");
        var triggerIndex = Array.FindIndex(
            events,
            gameEvent => string.Equals(gameEvent.Kind, "BATTLEFIELD_TRIGGER_RESOLVED", StringComparison.Ordinal)
                && string.Equals(gameEvent.Payload["trigger"] as string, TriggerKinds.BattlefieldConquerReadyEquipment, StringComparison.Ordinal));
        Assert.True(triggerIndex > conqueredIndex, $"Expected Moonveil Altar trigger after conquest: {JsonSerializer.Serialize(result.Events)}");

        var triggerEvent = events[triggerIndex];
        Assert.Equal("P1", triggerEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(MoonveilAltarBattlefieldConquerReadyEquipmentCardNo, triggerEvent.Payload["battlefieldCardNo"]);
        Assert.Equal(attackerObjectId, triggerEvent.Payload["sourceObjectId"]);
        Assert.Equal(equipmentObjectId, triggerEvent.Payload["equipmentObjectId"]);
        Assert.Equal(true, triggerEvent.Payload["detachesArmament"]);

        var readyEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "EQUIPMENT_READIED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["sourceObjectId"] as string, equipmentObjectId, StringComparison.Ordinal));
        Assert.Equal("P1", readyEvent.Payload["playerId"]);
        Assert.Equal(TriggerKinds.BattlefieldConquerReadyEquipment, readyEvent.Payload["reason"]);
        Assert.Equal(true, readyEvent.Payload["wasExhausted"]);
        Assert.Equal(false, readyEvent.Payload["isExhausted"]);

        var detachEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "EQUIPMENT_DETACHED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["equipmentObjectId"] as string, equipmentObjectId, StringComparison.Ordinal));
        Assert.Equal("P1", detachEvent.Payload["playerId"]);
        Assert.Equal(TriggerKinds.BattlefieldConquerReadyEquipment, detachEvent.Payload["abilityId"]);
        Assert.Equal(attackerObjectId, detachEvent.Payload["unitObjectId"]);
        Assert.Equal(attackerObjectId, detachEvent.Payload["previousAttachedToObjectId"]);

        Assert.Contains(equipmentObjectId, result.State.PlayerZones["P1"].Base);
        Assert.False(result.State.CardObjects[equipmentObjectId].IsExhausted);
        Assert.Null(result.State.CardObjects[equipmentObjectId].AttachedToObjectId);
        Assert.DoesNotContain(defenderObjectId, result.State.PlayerZones["P2"].Battlefields);
        AssertNoHiddenZoneLeak(result);
    }

    private static (IReadOnlyList<string> RuneObjectIds, IReadOnlyList<string> EffectIds)
        AssertBattlefieldConquerReadyRunesAtEndScheduled(
            ResolutionResult beforeBattle,
            ResolutionResult result)
    {
        var battlefieldObjectId = BattlefieldObjectIdForCardNo(
            result.State,
            "P1",
            MountTargonBattlefieldConquerReadyRunesAtEndCardNo);
        var attackerObjectId = FindBattlefieldUnitByCardNo(
            beforeBattle.State,
            "P1",
            WildclawBeastmasterCardNo,
            battlefieldObjectId,
            readyOnly: true)
            ?? throw new InvalidOperationException("B0 Mount Targon assertion could not locate Wildclaw Beastmaster before battle.");
        var defenderObjectId = FindBattlefieldUnitByCardNo(
            beforeBattle.State,
            "P2",
            WatchfulSentinelCardNo,
            battlefieldObjectId,
            readyOnly: true)
            ?? throw new InvalidOperationException("B0 Mount Targon assertion could not locate Watchful Sentinel before battle.");
        var expectedRuneObjectIds = beforeBattle.State.PlayerZones["P1"].Base
            .Where(objectId => beforeBattle.State.CardObjects.TryGetValue(objectId, out var cardObject)
                && cardObject.Tags.Contains(CardObjectTags.RuneCard, StringComparer.Ordinal)
                && (string.Equals(cardObject.ControllerId, "P1", StringComparison.Ordinal)
                    || string.Equals(cardObject.OwnerId, "P1", StringComparison.Ordinal)))
            .Take(2)
            .ToArray();
        Assert.Equal(2, expectedRuneObjectIds.Length);
        Assert.All(expectedRuneObjectIds, objectId => Assert.True(beforeBattle.State.CardObjects[objectId].IsExhausted));
        Assert.Null(result.State.PendingPayment);

        var events = result.Events.ToArray();
        var conqueredIndex = Array.FindIndex(
            events,
            gameEvent => string.Equals(gameEvent.Kind, "BATTLEFIELD_CONQUERED", StringComparison.Ordinal)
                && string.Equals(gameEvent.Payload["battlefieldId"] as string, battlefieldObjectId, StringComparison.Ordinal));
        Assert.True(conqueredIndex >= 0, $"Expected battlefield conquered before Mount Targon trigger: {JsonSerializer.Serialize(result.Events)}");
        var triggerIndex = Array.FindIndex(
            events,
            gameEvent => string.Equals(gameEvent.Kind, "BATTLEFIELD_TRIGGER_RESOLVED", StringComparison.Ordinal)
                && string.Equals(gameEvent.Payload["trigger"] as string, TriggerKinds.BattlefieldConquerReadyRunesAtEnd, StringComparison.Ordinal));
        Assert.True(triggerIndex > conqueredIndex, $"Expected Mount Targon trigger after conquest: {JsonSerializer.Serialize(result.Events)}");

        var triggerEvent = events[triggerIndex];
        Assert.Equal("P1", triggerEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(MountTargonBattlefieldConquerReadyRunesAtEndCardNo, triggerEvent.Payload["battlefieldCardNo"]);
        Assert.Equal(attackerObjectId, triggerEvent.Payload["sourceObjectId"]);
        Assert.Equal(expectedRuneObjectIds, Assert.IsAssignableFrom<IReadOnlyList<string>>(triggerEvent.Payload["runeObjectIds"]));
        var effectIds = Assert.IsAssignableFrom<IReadOnlyList<string>>(triggerEvent.Payload["effectIds"]);
        Assert.Equal(expectedRuneObjectIds.Length, effectIds.Count);

        var scheduledEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "RUNE_READY_SCHEDULED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["abilityId"] as string, TriggerKinds.BattlefieldConquerReadyRunesAtEnd, StringComparison.Ordinal));
        Assert.Equal("P1", scheduledEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, scheduledEvent.Payload["sourceObjectId"]);
        Assert.Equal(expectedRuneObjectIds, Assert.IsAssignableFrom<IReadOnlyList<string>>(scheduledEvent.Payload["runeObjectIds"]));
        Assert.Equal(effectIds, Assert.IsAssignableFrom<IReadOnlyList<string>>(scheduledEvent.Payload["effectIds"]));

        foreach (var effectId in effectIds)
        {
            Assert.Contains(effectId, result.State.UntilEndOfTurnEffects);
        }

        foreach (var runeObjectId in expectedRuneObjectIds)
        {
            Assert.True(result.State.CardObjects[runeObjectId].IsExhausted);
        }

        Assert.DoesNotContain(defenderObjectId, result.State.PlayerZones["P2"].Battlefields);
        AssertNoHiddenZoneLeak(result);
        return (expectedRuneObjectIds, effectIds.ToArray());
    }

    private static void AssertBattlefieldConquerReadyRunesAtEndCompleted(
        ResolutionResult afterBattle,
        ResolutionResult result,
        IReadOnlyList<string> runeObjectIds,
        IReadOnlyList<string> effectIds)
    {
        Assert.NotEmpty(runeObjectIds);
        Assert.NotEmpty(effectIds);
        Assert.All(effectIds, effectId => Assert.Contains(effectId, afterBattle.State.UntilEndOfTurnEffects));
        Assert.All(effectIds, effectId => Assert.DoesNotContain(effectId, result.State.UntilEndOfTurnEffects));
        foreach (var runeObjectId in runeObjectIds)
        {
            Assert.Contains(runeObjectId, result.State.PlayerZones["P1"].Base);
            Assert.False(result.State.CardObjects[runeObjectId].IsExhausted);
        }

        AssertNoHiddenZoneLeak(result);
    }

    private static void AssertBattlefieldConquerMillResolved(
        ResolutionResult beforeBattle,
        ResolutionResult result)
    {
        var battlefieldObjectId = BattlefieldObjectIdForCardNo(
            result.State,
            "P1",
            MinefieldBattlefieldConquerMillCardNo);
        var attackerObjectId = FindBattlefieldUnitByCardNo(
            beforeBattle.State,
            "P1",
            WildclawBeastmasterCardNo,
            battlefieldObjectId,
            readyOnly: true)
            ?? throw new InvalidOperationException("B0 Minefield assertion could not locate Wildclaw Beastmaster before battle.");
        var defenderObjectId = FindBattlefieldUnitByCardNo(
            beforeBattle.State,
            "P2",
            WatchfulSentinelCardNo,
            battlefieldObjectId,
            readyOnly: true)
            ?? throw new InvalidOperationException("B0 Minefield assertion could not locate Watchful Sentinel before battle.");
        var expectedMilledObjectIds = beforeBattle.State.PlayerZones["P1"].MainDeck.Take(2).ToArray();
        Assert.Equal(2, expectedMilledObjectIds.Length);
        Assert.Null(result.State.PendingPayment);

        var events = result.Events.ToArray();
        var conqueredIndex = Array.FindIndex(
            events,
            gameEvent => string.Equals(gameEvent.Kind, "BATTLEFIELD_CONQUERED", StringComparison.Ordinal)
                && string.Equals(gameEvent.Payload["battlefieldId"] as string, battlefieldObjectId, StringComparison.Ordinal));
        Assert.True(conqueredIndex >= 0, $"Expected battlefield conquered before Minefield trigger: {JsonSerializer.Serialize(result.Events)}");
        var triggerIndex = Array.FindIndex(
            events,
            gameEvent => string.Equals(gameEvent.Kind, "BATTLEFIELD_TRIGGER_RESOLVED", StringComparison.Ordinal)
                && string.Equals(gameEvent.Payload["trigger"] as string, TriggerKinds.BattlefieldConquerMill, StringComparison.Ordinal));
        Assert.True(triggerIndex > conqueredIndex, $"Expected Minefield trigger after conquest: {JsonSerializer.Serialize(result.Events)}");

        var triggerEvent = events[triggerIndex];
        Assert.Equal("P1", triggerEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(MinefieldBattlefieldConquerMillCardNo, triggerEvent.Payload["battlefieldCardNo"]);
        Assert.Equal(attackerObjectId, triggerEvent.Payload["sourceObjectId"]);
        Assert.Equal(2, triggerEvent.Payload["count"]);

        var millEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "CARDS_MILLED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["sourceObjectId"] as string, battlefieldObjectId, StringComparison.Ordinal));
        Assert.Equal("P1", millEvent.Payload["playerId"]);
        Assert.Equal(2, millEvent.Payload["count"]);
        Assert.Equal(TriggerZones.MainDeck, millEvent.Payload["sourceZone"]);
        Assert.Equal(TriggerZones.Graveyard, millEvent.Payload["destinationZone"]);
        Assert.Equal(expectedMilledObjectIds, Assert.IsAssignableFrom<IReadOnlyList<string>>(millEvent.Payload["cardIds"]));

        Assert.Equal(
            beforeBattle.State.PlayerZones["P1"].MainDeck.Skip(expectedMilledObjectIds.Length).ToArray(),
            result.State.PlayerZones["P1"].MainDeck);
        Assert.Equal(
            expectedMilledObjectIds,
            result.State.PlayerZones["P1"].Graveyard.TakeLast(expectedMilledObjectIds.Length).ToArray());
        Assert.DoesNotContain(defenderObjectId, result.State.PlayerZones["P2"].Battlefields);
        AssertNoHiddenZoneLeak(result);
    }

    private static void AssertBattlefieldFriendlySpellDrawResolved(
        ResolutionResult beforeSpell,
        ResolutionResult result)
    {
        var battlefieldObjectId = BattlefieldObjectIdForCardNo(
            result.State,
            "P1",
            DreamTreeBattlefieldFriendlySpellDrawCardNo);
        var drawnObjectId = beforeSpell.State.PlayerZones["P1"].MainDeck.FirstOrDefault()
            ?? throw new InvalidOperationException("B0 Dream Tree assertion expected at least one P1 main-deck card to draw.");
        var targetObjectId = FindBattlefieldUnitByCardNo(
            beforeSpell.State,
            "P1",
            WildclawBeastmasterCardNo,
            battlefieldObjectId)
            ?? throw new InvalidOperationException("B0 Dream Tree assertion could not locate Wildclaw Beastmaster at Dream Tree.");

        var triggerEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "BATTLEFIELD_TRIGGER_RESOLVED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["trigger"] as string, TriggerKinds.BattlefieldFriendlySpellDraw, StringComparison.Ordinal));
        Assert.Equal("P1", triggerEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(DreamTreeBattlefieldFriendlySpellDrawCardNo, triggerEvent.Payload["battlefieldCardNo"]);
        Assert.Equal(1, triggerEvent.Payload["drawCount"]);
        Assert.Equal(SavageStrengthSpellCardNo, triggerEvent.Payload["playedCardNo"]);

        var drawEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "CARD_DRAWN", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["playerId"] as string, "P1", StringComparison.Ordinal));
        Assert.Equal(1, drawEvent.Payload["count"]);
        if (drawEvent.Payload.TryGetValue("cardIds", out var drawnCardIds))
        {
            Assert.Equal([drawnObjectId], Assert.IsType<string[]>(drawnCardIds));
        }
        Assert.Contains(drawnObjectId, result.State.PlayerZones["P1"].Hand);
        Assert.DoesNotContain(drawnObjectId, result.State.PlayerZones["P1"].MainDeck);
        Assert.Equal(beforeSpell.State.PlayerZones["P1"].Hand.Count, result.State.PlayerZones["P1"].Hand.Count);
        Assert.Equal(beforeSpell.State.PlayerZones["P1"].MainDeck.Count - 1, result.State.PlayerZones["P1"].MainDeck.Count);
        Assert.Contains(
            result.State.UntilEndOfTurnEffects,
            effectId => string.Equals(
                effectId,
                $"BATTLEFIELD_FRIENDLY_SPELL_DRAW_USED:P1:{battlefieldObjectId}",
                StringComparison.Ordinal));
        Assert.Contains(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "STACK_ITEM_ADDED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["cardNo"] as string, SavageStrengthSpellCardNo, StringComparison.Ordinal)
            && Assert.IsType<string[]>(gameEvent.Payload["targetObjectIds"]).Contains(targetObjectId, StringComparer.Ordinal));
        AssertNoHiddenZoneLeak(result);
    }

    private static void AssertBattlefieldSpellPowerBonusResolved(
