        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(WasteHallBattlefieldSpellPowerBonusCardNo, triggerEvent.Payload["battlefieldCardNo"]);
