            PoroForgeBattlefieldLegendAttachArmamentCardNo);
        var legendObjectId = Assert.Single(current.State.PlayerZones[playerId].LegendZone);
        var targetObjectId = FindBaseUnitByCardNo(
            current.State,
            playerId,
            AggressiveDragonhoundCardNo)
            ?? throw new InvalidOperationException("B0 Poro Forge driver could not find Aggressive Dragonhound in P1 base.");
        var equipmentObjectId = FindBaseArmamentByCardNo(
            current.State,
            playerId,
            LongSwordEquipmentCardNo)
            ?? throw new InvalidOperationException("B0 Poro Forge driver could not find Long Sword armament in P1 base.");

        var legalSourceIds = candidate.Sources?.Select(choice => choice.Id).ToHashSet(StringComparer.Ordinal)
            ?? [];
        var legalModeIds = candidate.Modes?.Select(choice => choice.Id).ToHashSet(StringComparer.Ordinal)
            ?? [];
        Assert.Contains(legendObjectId, legalSourceIds);
        Assert.Contains(BattlefieldGrantedLegendAttachArmamentAbilityId, legalModeIds);

        var metadata = Assert.IsAssignableFrom<IReadOnlyDictionary<string, object?>>(candidate.Metadata);
        var sourceRequirement = Assert.Single(
            Assert.IsAssignableFrom<IEnumerable<IReadOnlyDictionary<string, object?>>>(metadata["sourceRequirements"]),
            requirement => string.Equals(requirement["sourceObjectId"] as string, legendObjectId, StringComparison.Ordinal)
                && string.Equals(requirement["abilityId"] as string, BattlefieldGrantedLegendAttachArmamentAbilityId, StringComparison.Ordinal));
        Assert.Equal(2, Assert.IsType<int>(sourceRequirement["minTargetCount"]));
        Assert.Equal(2, Assert.IsType<int>(sourceRequirement["maxTargetCount"]));
        Assert.True(Assert.IsType<bool>(sourceRequirement["exhaustsSource"]));
        var targetChoicesByIndex = Assert.IsAssignableFrom<IReadOnlyDictionary<string, IReadOnlyList<ActionPromptChoiceDto>>>(
            sourceRequirement["targetChoicesByIndex"]);
        Assert.Contains(targetObjectId, targetChoicesByIndex["0"].Select(choice => choice.Id));
        Assert.Contains(equipmentObjectId, targetChoicesByIndex["1"].Select(choice => choice.Id));

        var command = new LegendActCommand(
            legendObjectId,
            BattlefieldGrantedLegendAttachArmamentAbilityId,
            [targetObjectId, equipmentObjectId]);
        var result = await session.SubmitAsync(
            playerId,
            intentId,
            command,
            RawCommand(command),
            CancellationToken.None);
        AssertAccepted(result);
        AssertNoHiddenZoneLeak(result);
        return result;
    }

    private static async ValueTask<ResolutionResult> SubmitBattlefieldLegendAttachArmamentRejectedAsync(
        MatchSession session,
        ResolutionResult current,
        string playerId,
        string intentId)
    {
        Assert.Equal(playerId, current.State.ActivePlayerId);
        var legendObjectId = Assert.Single(current.State.PlayerZones[playerId].LegendZone);
        var targetObjectId = FindBaseUnitByCardNo(
            current.State,
            playerId,
            AggressiveDragonhoundCardNo)
            ?? throw new InvalidOperationException("B0 Poro Forge rejected driver could not find Aggressive Dragonhound in P1 base.");
        var equipmentObjectId = FindBaseArmamentByCardNo(
            current.State,
            playerId,
            LongSwordEquipmentCardNo)
            ?? throw new InvalidOperationException("B0 Poro Forge rejected driver could not find Long Sword armament in P1 base.");

        var candidate = EnabledCandidate(current.Prompts[playerId], CommandTypes.LegendAct);
        if (candidate is not null)
        {
            var legalModeIds = candidate.Modes?.Select(choice => choice.Id).ToHashSet(StringComparer.Ordinal)
                ?? [];
            Assert.DoesNotContain(BattlefieldGrantedLegendAttachArmamentAbilityId, legalModeIds);
            var metadata = Assert.IsAssignableFrom<IReadOnlyDictionary<string, object?>>(candidate.Metadata);
            if (metadata.TryGetValue("sourceRequirements", out var rawSourceRequirements))
            {
                var sourceRequirements = Assert.IsAssignableFrom<IEnumerable<IReadOnlyDictionary<string, object?>>>(rawSourceRequirements);
                Assert.DoesNotContain(sourceRequirements, requirement =>
                    string.Equals(requirement["sourceObjectId"] as string, legendObjectId, StringComparison.Ordinal)
                    && string.Equals(requirement["abilityId"] as string, BattlefieldGrantedLegendAttachArmamentAbilityId, StringComparison.Ordinal));
            }
        }

        var command = new LegendActCommand(
            legendObjectId,
            BattlefieldGrantedLegendAttachArmamentAbilityId,
            [targetObjectId, equipmentObjectId]);
        var result = await session.SubmitAsync(
            playerId,
            intentId,
            command,
            RawCommand(command),
            CancellationToken.None);
        AssertNoHiddenZoneLeak(result);
        return result;
    }

    private static async ValueTask<ResolutionResult> SubmitBattlefieldBattleDestroyedRecallDeclareBattleAsync(
        MatchSession session,
        ResolutionResult current,
        string attackingPlayerId,
        string intentId)
    {
        Assert.Equal(attackingPlayerId, current.State.ActivePlayerId);
        var defendingPlayerId = OpponentOf(current.State, attackingPlayerId);
        var candidate = EnabledCandidate(current.Prompts[attackingPlayerId], CommandTypes.DeclareBattle)
            ?? throw new InvalidOperationException($"B0 Blood Altar driver could not find DECLARE_BATTLE for {attackingPlayerId}: {DescribeState(current.State)}");
        var battlefieldId = BattlefieldObjectIdForCardNo(
            current.State,
            defendingPlayerId,
            BloodAltarBattlefieldDestroyedRecallCardNo);
        var attackerObjectId = FindBattlefieldUnitByCardNo(
            current.State,
            attackingPlayerId,
            WildclawBeastmasterCardNo,
            battlefieldId,
            readyOnly: true)
            ?? throw new InvalidOperationException("B0 Blood Altar driver could not find a ready Wildclaw Beastmaster attacker.");
        var defenderObjectId = FindBattlefieldUnitByCardNo(
            current.State,
            defendingPlayerId,
            WatchfulSentinelCardNo,
            battlefieldId,
            readyOnly: true)
            ?? throw new InvalidOperationException("B0 Blood Altar driver could not find a ready Watchful Sentinel defender.");

        var legalSourceIds = candidate.Sources?.Select(choice => choice.Id).ToHashSet(StringComparer.Ordinal)
            ?? [];
        var legalTargetIds = candidate.Targets?.Select(choice => choice.Id).ToHashSet(StringComparer.Ordinal)
            ?? [];
        var legalDestinationIds = candidate.Destinations?.Select(choice => choice.Id).ToHashSet(StringComparer.Ordinal)
            ?? [];
        Assert.Contains(attackerObjectId, legalSourceIds);
        Assert.Contains(defenderObjectId, legalTargetIds);
        Assert.Contains(battlefieldId, legalDestinationIds);

        var command = new DeclareBattleCommand(
            battlefieldId,
            [attackerObjectId],
            [defenderObjectId],
            OptionalCosts: ["COMBAT_ASSIGNMENT"]);
        var declared = await session.SubmitAsync(
            attackingPlayerId,
            intentId,
            command,
            RawCommand(command),
            CancellationToken.None);
        AssertAccepted(declared);
        AssertNoHiddenZoneLeak(declared);

        var result = await PassOpenBattleResponseAsync(session, declared, $"{intentId}-battle-response");
        result = await ResolveOpenBattleDamageAssignmentsAsync(session, result, $"{intentId}-assign-damage");
        result = await PassOpenBattleResponseAsync(session, result, $"{intentId}-battle-response-after-assignment");
        Assert.Null(result.State.PendingPayment);
        AssertNoHiddenZoneLeak(result);
        return result;
    }

