    private static MatchState BuildBattlefieldFirstTurnReplayInitialState(MatchState state, string sourceBattlefieldCardNo)
    {
        _ = BattlefieldObjectIdForCardNo(
            state,
            "P1",
            sourceBattlefieldCardNo);
        var playerZones = state.PlayerZones.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var objectLocations = state.ObjectLocations.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var cardObjects = state.CardObjects.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        foreach (var (playerId, zones) in state.PlayerZones)
        {
            var battlefieldCardObjectIds = zones.Battlefields
                .Where(objectId => state.CardObjects.TryGetValue(objectId, out var cardObject)
                    && cardObject.Tags.Contains("CARD_TYPE:BATTLEFIELD", StringComparer.Ordinal))
                .ToArray();
            var nonBattlefieldObjectIds = zones.Battlefields
                .Where(objectId => !battlefieldCardObjectIds.Contains(objectId, StringComparer.Ordinal))
                .ToArray();
            if (nonBattlefieldObjectIds.Length == 0)
            {
                continue;
            }

            playerZones[playerId] = zones with
            {
                Battlefields = battlefieldCardObjectIds,
                Base = zones.Base
                    .Concat(nonBattlefieldObjectIds)
                    .Distinct(StringComparer.Ordinal)
                    .ToArray()
            };
            foreach (var objectId in nonBattlefieldObjectIds)
            {
                objectLocations[objectId] = new ObjectLocationState(playerId, "BASE");
                cardObjects[objectId] = cardObjects[objectId] with
                {
                    IsAttacking = false,
                    IsDefending = false
                };
            }
        }

        return state with
        {
            Status = MatchStatuses.InProgress,
            TurnNumber = 1,
            ActivePlayerId = "P1",
            TurnPlayerId = "P1",
            OpeningSecondActionPlayerId = "P2",
            Phase = MatchPhases.Main,
            TimingState = TimingStates.NeutralOpen,
            FocusPlayerId = null,
            PassedFocusPlayerIds = [],
            PriorityPlayerId = null,
            PassedPriorityPlayerIds = [],
            StackItems = [],
            WinnerPlayerId = null,
            PlayerZones = playerZones,
            ObjectLocations = objectLocations,
            CardObjects = cardObjects,
            UntilEndOfTurnEffects = [],
            PlayerScores = state.Seats.Keys.ToDictionary(playerId => playerId, _ => 0, StringComparer.Ordinal),
            PlayerCardsPlayedThisTurn = state.Seats.Keys.ToDictionary(playerId => playerId, _ => 0, StringComparer.Ordinal)
        };
    }

    private static MatchState BuildBattlefieldScoreDelayFirstTurnReplayInitialState(MatchState state)
    {
        var replayState = BuildBattlefieldFirstTurnReplayInitialState(
            state,
            ForgottenMonumentBattlefieldCardNo);
        if (replayState.PlayerZones["P1"].Battlefields.Any(objectId =>
            replayState.CardObjects.TryGetValue(objectId, out var cardObject)
            && string.Equals(cardObject.CardNo, FirstTurnScoreBattlefieldCardNo, StringComparison.Ordinal)))
        {
            return replayState;
        }

        const string scoreSourceObjectId = "B0-P1-BATTLEFIELD-GLORY-ARENA-SCORE-DELAY";
        var playerZones = replayState.PlayerZones.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var p1Zones = playerZones["P1"];
        playerZones["P1"] = p1Zones with
        {
            Battlefields = p1Zones.Battlefields
                .Append(scoreSourceObjectId)
                .Distinct(StringComparer.Ordinal)
                .ToArray()
        };
        var cardObjects = replayState.CardObjects.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        cardObjects[scoreSourceObjectId] = new CardObjectState(
            scoreSourceObjectId,
            cardNo: FirstTurnScoreBattlefieldCardNo,
            tags: ["CARD_TYPE:BATTLEFIELD"],
            ownerId: "P1",
            controllerId: "P1");
        var objectLocations = replayState.ObjectLocations.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        objectLocations[scoreSourceObjectId] = new ObjectLocationState("P1", "BATTLEFIELD");

        return replayState with
        {
            PlayerZones = playerZones,
            CardObjects = cardObjects,
            ObjectLocations = objectLocations
        };
    }

    private static MatchState BuildBattlefieldWinningScoreIncreaseFirstTurnReplayInitialState(MatchState state)
    {
        var replayState = BuildBattlefieldFirstTurnReplayInitialState(
            state,
            WinningScoreIncreaseBattlefieldCardNo);
        replayState = KeepOnlyFirstBattlefieldSource(
            replayState,
            WinningScoreIncreaseBattlefieldCardNo);
        replayState = EnsureP1BattlefieldSource(
            replayState,
            FirstTurnScoreBattlefieldCardNo,
            "B0-P1-BATTLEFIELD-GLORY-ARENA-WINNING-SCORE");

        return replayState with
        {
            PlayerScores = replayState.Seats.Keys.ToDictionary(
                playerId => playerId,
                playerId => string.Equals(playerId, "P2", StringComparison.Ordinal) ? 7 : 0,
                StringComparer.Ordinal)
        };
    }

    private static MatchState KeepOnlyFirstBattlefieldSource(MatchState state, string battlefieldCardNo)
    {
        var matchingObjectIds = state.PlayerZones
            .SelectMany(entry => entry.Value.Battlefields.Select(objectId => (PlayerId: entry.Key, ObjectId: objectId)))
            .Where(entry => state.CardObjects.TryGetValue(entry.ObjectId, out var cardObject)
                && string.Equals(cardObject.CardNo, battlefieldCardNo, StringComparison.Ordinal))
            .ToArray();
        if (matchingObjectIds.Length <= 1)
        {
            return state;
        }

        var extraObjectIdsByPlayer = matchingObjectIds
            .Skip(1)
            .GroupBy(entry => entry.PlayerId, StringComparer.Ordinal)
            .ToDictionary(
                group => group.Key,
                group => group.Select(entry => entry.ObjectId).ToArray(),
                StringComparer.Ordinal);
        var playerZones = state.PlayerZones.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        foreach (var (playerId, extraObjectIds) in extraObjectIdsByPlayer)
        {
            var zones = playerZones[playerId];
            playerZones[playerId] = zones with
            {
                Battlefields = zones.Battlefields
                    .Where(objectId => !extraObjectIds.Contains(objectId, StringComparer.Ordinal))
                    .ToArray(),
                Base = zones.Base
                    .Concat(extraObjectIds)
                    .Distinct(StringComparer.Ordinal)
                    .ToArray()
            };
        }

        var objectLocations = state.ObjectLocations.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        foreach (var (playerId, extraObjectIds) in extraObjectIdsByPlayer)
        {
            foreach (var objectId in extraObjectIds)
            {
                objectLocations[objectId] = new ObjectLocationState(playerId, "BASE");
            }
        }

        return state with
        {
            PlayerZones = playerZones,
            ObjectLocations = objectLocations
        };
    }

    private static MatchState EnsureP1BattlefieldSource(
        MatchState state,
        string battlefieldCardNo,
        string fallbackObjectId)
    {
        if (state.PlayerZones["P1"].Battlefields.Any(objectId =>
            state.CardObjects.TryGetValue(objectId, out var cardObject)
            && string.Equals(cardObject.CardNo, battlefieldCardNo, StringComparison.Ordinal)))
        {
            return state;
        }

        var playerZones = state.PlayerZones.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var p1Zones = playerZones["P1"];
        playerZones["P1"] = p1Zones with
        {
            Battlefields = p1Zones.Battlefields
                .Append(fallbackObjectId)
                .Distinct(StringComparer.Ordinal)
                .ToArray()
        };
        var cardObjects = state.CardObjects.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        cardObjects[fallbackObjectId] = new CardObjectState(
            fallbackObjectId,
            cardNo: battlefieldCardNo,
            tags: ["CARD_TYPE:BATTLEFIELD"],
            ownerId: "P1",
            controllerId: "P1");
        var objectLocations = state.ObjectLocations.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        objectLocations[fallbackObjectId] = new ObjectLocationState("P1", "BATTLEFIELD");

        return state with
        {
            PlayerZones = playerZones,
            CardObjects = cardObjects,
            ObjectLocations = objectLocations
        };
    }

